using PrincesPalace.Domain.Content;
using UnityEngine;

namespace PrincesPalace.Content
{
    // One rewards.json row, generated by ContentBuilder and never hand-edited.
    // The fields live in ResolvedRewardSource; this asset stores it.
    public class RewardSourceDefinition : ScriptableObject, IOrderedContent
    {
        [SerializeField] private ResolvedRewardSource data = new ResolvedRewardSource();

        public ResolvedRewardSource Data => data;

        public string id => data != null ? data.Id : "";

        // Editor-only, and the only assignment to `data` anywhere.
        internal void SetData(ResolvedRewardSource value) => data = value ?? new ResolvedRewardSource();

        public int SortOrder => data != null ? data.SortOrder : 0;
    }
}
